DELETE FROM dashboard_integration_alert
WHERE status = 'ACKNOWLEDGED' AND last_at < #{cutoff}
ORDER BY last_at, alert_id LIMIT #{limit}

DELETE FROM sys_oper_log
WHERE request_method = 'POST' AND oper_time < #{cutoff}
  AND oper_url REGEXP '^(/api)?/dashboard/(dataset/[0-9]+/test|integration/endpoints/[A-Za-z0-9._-]+/[A-Za-z0-9._-]+/test)$'
ORDER BY oper_time, oper_id LIMIT #{limit}
